nodes = ['N_c1','N_c2','N_c3','X2','X3']
measurements = [
    ('N_c1','N_c2',10.0),
    ('N_c1','N_c3',25.0),
    ('N_c1','X2',5.0),
    ('N_c1','X3',45.0),
    ('N_c2','N_c3',15.0),
    ('N_c2','X2',15.0),
    ('N_c2','X3',35.0),
    ('N_c3','X2',30.0),
    ('N_c3','X3',20.0),
    ('X2','X3',50.0)
]
all_edges = list(itertools.combinations(nodes,2))

def find_path(adj, start, end):
    from collections import deque
    q = deque([start])
    parent = {start: None}
    while q:
        u = q.popleft()
        if u == end:
            break
        for v in adj[u]:
            if v not in parent:
                parent[v] = u
                q.append(v)
    if end not in parent:
        return None
    path = []
    cur = end
    while parent[cur] is not None:
        p = parent[cur]
        path.append(tuple(sorted((cur, p))))
        cur = p
    return path

solutions = []
for edges in itertools.combinations(all_edges, 4):
    # build adjacency list
    adj = {n: [] for n in nodes}
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    # check connectivity
    from collections import deque
    visited = set()
    q = deque([nodes[0]])
    while q:
        u = q.popleft()
        if u in visited:
            continue
        visited.add(u)
        for v in adj[u]:
            if v not in visited:
                q.append(v)
    if len(visited) != len(nodes):
        continue
    # build linear equations: each measurement is sum of resistances on path
    A = []
    b = []
    valid = True
    for a, bnode, val in measurements:
        path = find_path(adj, a, bnode)
        if path is None:
            valid = False
            break
        coeff = [1 if tuple(sorted(e)) in path else 0 for e in edges]
        A.append(coeff)
        b.append(val)
    if not valid:
        continue
    A = np.array(A, dtype=float)
    b = np.array(b, dtype=float)
    # solve
    try:
        sol, residuals, rank, s = np.linalg.lstsq(A, b, rcond=None)
    except Exception:
        continue
    if np.allclose(A.dot(sol), b, atol=1e-6) and np.all(sol > 0):
        solutions.append((edges, sol))
        break

if solutions:
    edges, sol = solutions[0]
    res_dict = {f'R{i+1}': round(sol[i], 6) for i in range(len(sol))}
    conn = [[a, b, f'R{i+1}'] for i, (a, b) in enumerate(edges)]
    print(json.dumps({'resistors': res_dict, 'connections': conn}, indent=2))
else:
    print('No solution found')
